/* ========================================================
   BANCOS DE PREGUNTAS (4 EXÁMENES OFICIALES FNMT)
   ======================================================== */



// --- EXAMEN 1: FNMT 2022 (100 PREGUNTAS COMPLETAS) ---
const examFNMT2022 = [
  // 1 - 5 (Inicia el banco oficial)
  { question: "¿Qué tipo de motor acciona el movimiento de la cuchilla en las guillotinas POLAR 115?", options: ["Motor de corriente alterna con freno electromagnético", "Motor de corriente continua", "Motor paso a paso"], correct: 0, explanation: "Las guillotinas POLAR utilizan un motor de corriente alterna equipado con freno electromagnético para garantizar paradas de seguridad instantáneas y precisas.", source: "Examen Oficial FNMT 2022 (Pregunta 1)" },
  { question: "¿Cuál es la dureza Rockwell (HRC) del inserto de acero rápido (HSS) en las cuchillas estándar POLAR?", options: ["61 - 63 HRC", "18 - 20 HRC", "80 - 90 HRC"], correct: 0, explanation: "El inserto de aleación de acero rápido (HSS) de la cuchilla alcanza una dureza de 61 a 63 HRC para resistir el desgaste prolongado.", source: "Examen Oficial FNMT 2022 (Pregunta 2)" },
  { question: "En la POLAR 115 XT, ¿cuál es la fuerza máxima ejercida al accionar el pisón mediante el pedal mecánico?", options: ["300 N", "400 N", "500 N"], correct: 0, explanation: "La presión de comprobación visual sobre el pedal aplica una fuerza limitada por seguridad a un máximo de 300 N.", source: "Examen Oficial FNMT 2022 (Pregunta 3)" },
  { question: "Según el manual técnico, ¿cuál es la presión de prensado recomendada para el papel Offset?", options: ["2.000 daN", "3.000 daN", "1.000 daN"], correct: 0, explanation: "Para papel de impresión offset normal se establece una presión de prensado estándar de 2.000 daN.", source: "Examen Oficial FNMT 2022 (Pregunta 4)" },
  { question: "¿Cómo se debe colocar en la mesa de corte un papel con baja capacidad de deslizamiento?", options: ["Lo más a la izquierda posible", "Lo más a la derecha posible", "Es indiferente la posición"], correct: 0, explanation: "Para evitar el exceso de fricción con la regla lateral derecha, los materiales poco deslizantes se arriman a la izquierda.", source: "Examen Oficial FNMT 2022 (Pregunta 5)" },

  // 6 - 20 (Procedimientos de corte y mecánica)
  { question: "¿Qué elemento mecánico limita el recorrido inferior de la cuchilla para evitar que dañe la mesa metálica?", options: ["El listón sintético o cuadradillo de corte", "La escuadra trasera", "El husillo de elevación"], correct: 0, explanation: "El listón sintético suave absorbe el impacto final del filo al completar la carrera descendente.", source: "Examen Oficial FNMT 2022 (Pregunta 6)" },
  { question: "¿Cuántas posiciones de uso útiles ofrece un listón de corte de sección cuadrada?", options: ["8 posiciones distintas", "4 posiciones distintas", "2 posiciones distintas"], correct: 0, explanation: "Un listón cuadrado simétrico permite usar 2 cantos por cada uno de sus 4 lados (8 posiciones en total).", source: "Examen Oficial FNMT 2022 (Pregunta 7)" },
  { question: "¿Qué ángulo de bisel se recomienda para cortar soportes de alto gramaje y consistencia como el papel estucado?", options: ["Ángulo doble de 24° a 26°", "Ángulo simple de 16°", "Ángulo de 45°"], correct: 0, explanation: "El bisel doble da mayor soporte metálico a la arista, evitando muescas en papeles densos.", source: "Examen Oficial FNMT 2022 (Pregunta 8)" },
  { question: "¿Qué sucede si el bisel de la cuchilla es excesivamente agudo (p. ej. 18°) al cortar cartón duro?", options: ["El filo se dobla o mella rápidamente", "Aumenta la fuerza de soplado de la mesa", "El pisón no ejerce presión"], correct: 0, explanation: "Un bisel demasiado agudo carece del cuerpo de acero necesario para penetrar soportes duros sin deformarse.", source: "Examen Oficial FNMT 2022 (Pregunta 9)" },
  { question: "¿Qué función cumple el soplado de aire de la mesa (Eltrotact) en las guillotinas POLAR?", options: ["Formar un colchón de aire que facilita el desplazamiento y mitiga la electricidad estática", "Refrigerar los circuitos de la pantalla", "Aumentar la velocidad de bajada del pisón"], correct: 0, explanation: "El soplado reduce el rozamiento de las pilas pesadas de papel y neutraliza la estática.", source: "Examen Oficial FNMT 2022 (Pregunta 10)" },
  { question: "¿Qué causa el defecto conocido como 'corte en seta'?", options: ["Presión insuficiente del pisón o aire atrapado en la pila", "Cuchilla excesivamente afilada", "Avance muy rápido de la escuadra"], correct: 0, explanation: "Al no haber suficiente presión de prensado, las hojas inferiores sobresalen hacia fuera al bajar la cuchilla.", source: "Examen Oficial FNMT 2022 (Pregunta 11)" },
  { question: "¿Cómo se corrige el arqueamiento superior del bloque cortado?", options: ["Aumentando la presión del pisón y revisando el afilado de la cuchilla", "Disminuyendo la velocidad de la escuadra", "Limpiando la mesa con disolvente"], correct: 0, explanation: "Un filo desafilado empuja las hojas superiores si el pisón no ejerce la fuerza adecuada.", source: "Examen Oficial FNMT 2022 (Pregunta 12)" },
  { question: "¿Qué lubricante debe aplicarse a las válvulas de bola de la mesa neumática?", options: ["Parafina seca especial", "Aceite mineral pesado de motor", "Grasa de litio concentrada"], correct: 0, explanation: "Las bolas neumáticas deben mantenerse limpias y tratadas con parafina o ceras secas para evitar atascos por polvo.", source: "Examen Oficial FNMT 2022 (Pregunta 13)" },
  { question: "¿Cuál es la tolerancia de precisión exigida en las guillotinas POLAR de alta gama?", options: ["±0,1 mm", "±1,0 mm", "±2,5 mm"], correct: 0, explanation: "Las guillotinas de precisión garantizan tolerancias estrictas de hasta una décima de milímetro.", source: "Examen Oficial FNMT 2022 (Pregunta 14)" },
  { question: "¿Qué comprobación de seguridad bimanual es obligatoria?", options: ["Verificar que la máquina se detiene al soltar cualquiera de los dos mandos", "Revisar la presión del neumático semanalmente", "Ajustar la iluminación de la mesa"], correct: 0, explanation: "El circuito bimanual debe interrumpir inmediatamente la bajada si se libera una de las manos.", source: "Examen Oficial FNMT 2022 (Pregunta 15)" },
  { question: "¿Qué dispositivo evita el atrapamiento bloqueando la cuchilla si se interrumpe la zona de corte?", options: ["La barrera fotoeléctrica infrarroja", "El contador de cortes", "El potenciómetro de la escuadra"], correct: 0, explanation: "La cortina de luz detecta cualquier intrusión y frena el embrague de la máquina instantáneamente.", source: "Examen Oficial FNMT 2022 (Pregunta 16)" },
  { question: "¿Para qué sirve el pedal de pre-presión en la guillotina?", options: ["Para bajar el pisón con baja presión y comprobar la línea visual de corte", "Para realizar un corte rápido de emergencia", "Para desplazar la escuadra trasera"], correct: 0, explanation: "El pedal permite posicionar el pisón suavemente sobre el pliego para verificar el ajuste del trazado.", source: "Examen Oficial FNMT 2022 (Pregunta 17)" },
  { question: "¿Qué ventaja principal ofrece la cuchilla con encastre de carburo de tungsteno (Widia)?", options: ["Duración del afilado de 5 a 10 veces superior a la de acero HSS", "Mayor flexibilidad frente a impactos con grapas", "Menor peso estructural"], correct: 0, explanation: "La extrema dureza de la Widia tolera millones de ciclos de corte antes de requerir un nuevo reafilado.", source: "Examen Oficial FNMT 2022 (Pregunta 18)" },
  { question: "¿Por qué se debe evitar cortar papel con grapas o impurezas metálicas con cuchillas de Widia?", options: ["Porque el metal duro es frágil frente a impactos secos y se astilla", "Porque se oxida de inmediato", "Porque descalibra la pantalla táctil"], correct: 0, explanation: "A pesar de su gran resistencia al desgaste, la Widia es quebradiza ante impactos contra objetos duros.", source: "Examen Oficial FNMT 2022 (Pregunta 19)" },
  { question: "¿Qué ajuste se debe realizar tras instalar una cuchilla recién afilada?", options: ["Regulación de la profundidad de corte con la excéntrica de ajuste", "Sustitución de la bomba de aceite", "Aumento de la velocidad de la escuadra"], correct: 0, explanation: "Al variar la altura de la cuchilla afilada, debe ajustarse el punto inferior para no marcar en exceso el listón.", source: "Examen Oficial FNMT 2022 (Pregunta 20)" },

  // 21 - 40 (Programación POLAR y Operativa)
  { question: "¿Qué realiza la función 'AutoTrim' en guillotinas automatizadas?", options: ["Apertura de la mesa frontal para la expulsión automática de virutas de refilado", "Afilado automático de la cuchilla", "Revisión del gramaje del papel"], correct: 0, explanation: "AutoTrim abre una ranura en la mesa para desechar las tiras sobrantes sin manipulación manual.", source: "Examen Oficial FNMT 2022 (Pregunta 21)" },
  { question: "¿Qué ocurre al aplicar excesiva presión de pisón sobre papel Offset poroso?", options: ["Deformación permanente y aplastamiento de la estructura del papel", "Chispas por fricción con la mesa", "Sobrecalentamiento del motor principal"], correct: 0, explanation: "Una presión desmedida destruye el volumen específico del papel dejando la huella de la suela del pisón.", source: "Examen Oficial FNMT 2022 (Pregunta 22)" },
  { question: "¿Qué accesorio evita marcar papeles delicados o gofrados?", options: ["La placa de recubrimiento flexible para la suela del pisón", "El listón de corte metálico", "Un baño de aceite siliconado"], correct: 0, explanation: "La suela blanda distribuye la fuerza de prensado sin aplastar los relieves del soporte.", source: "Examen Oficial FNMT 2022 (Pregunta 23)" },
  { question: "¿Qué define el término 'cota de retestado'?", options: ["El corte de limpieza inicial para dejar a escuadra los bordes del pliego", "La medida del lomo de un libro", "La velocidad de retorno del carro"], correct: 0, explanation: "El retestado es el refilado perimetral mínimo (1 a 3 mm) para eliminar irregularidades del bloque.", source: "Examen Oficial FNMT 2022 (Pregunta 24)" },
  { question: "¿Qué provoca el calentamiento excesivo del aceite hidráulico?", options: ["Uso continuado con nivel bajo de fluido o filtros obstruidos", "Trabajo prolongado con la mesa de aire", "Plegado incorrecto de pliegos"], correct: 0, explanation: "La falta de fluido o la suciedad en el circuito hidráulico elevan la temperatura y restan eficacia al prensado.", source: "Examen Oficial FNMT 2022 (Pregunta 25)" },
  { question: "En la POLAR 115 XT, ¿qué unidad de medida se emplea para programar la presión del pisón?", options: ["decanewton (daN)", "Bar", "PSI"], correct: 0, explanation: "El decanewton (daN) es la unidad estándar configurada en el software para indicar la fuerza hidráulica de prensado.", source: "Examen Oficial FNMT 2022 (Pregunta 26)" },
  { question: "¿A cuántos Newtons equivale 1 decanewton (daN)?", options: ["10 N", "100 N", "1.000 N"], correct: 0, explanation: "Por definición del SI, 1 decanewton es exactamente igual a 10 Newtons.", source: "Examen Oficial FNMT 2022 (Pregunta 27)" },
  { question: "¿Cómo se logra el posicionado de la escuadra tras teclear una medida teórica en POLAR XT?", options: ["Pulsando dos veces '=' o presionando la tecla táctil 'Liberar función'", "Manteniendo pulsado el pedal de pisón", "Presionando el botón de parada de emergencia"], correct: 0, explanation: "Es la secuencia de confirmación para habilitar el movimiento motorizado de la escuadra hacia la nueva cota.", source: "Examen Oficial FNMT 2022 (Pregunta 28)" },
  { question: "¿Qué tipo de papel requiere presiones de corte elevadas de hasta 4.000 daN?", options: ["Papel para etiquetas y soportes densos de alta consistencia", "Papel prensa", "Papel seda de bajo gramaje"], correct: 0, explanation: "La alta densidad del papel de etiquetas exige valores de prensado entre 3.500 y 4.000 daN.", source: "Examen Oficial FNMT 2022 (Pregunta 29)" },
  { question: "Para evitar la inclinación del bloque durante el corte, ¿qué dispositivo es clave?", options: ["La escuadra trasera perfectamente alineada a 90° con la mesa", "El nivel de aceite hidráulico", "El potenciómetro de pantalla"], correct: 0, explanation: "El escuadrado preciso a 90° de la guía trasera garantiza un corte ortogonal en todas las caras.", source: "Examen Oficial FNMT 2022 (Pregunta 30)" },
  { question: "¿Qué componente acciona el movimiento de ascenso y descenso del pisón?", options: ["Cilindro hidráulico impulsado por electroválvulas", "Motor paso a paso de corriente continua", "Cable mecánico de tracción"], correct: 0, explanation: "El pisón funciona mediante un circuito oleohidráulico de alta presión.", source: "Examen Oficial FNMT 2022 (Pregunta 31)" },
  { question: "¿Qué prueba se hace para comprobar si la cuchilla corta uniformemente en toda la longitud?", options: ["Prueba de corte con una sola hoja de papel fino a lo largo de toda la luz", "Medición de temperatura del motor", "Prueba de esfuerzo con plástico duro"], correct: 0, explanation: "Una hoja de papel fino permite verificar si el filo penetra homogéneamente sobre el listón en toda la luz de corte.", source: "Examen Oficial FNMT 2022 (Pregunta 32)" },
  { question: "¿Cómo se denomina la distancia entre la mesa y la parte inferior del pisón elevado?", options: ["Apertura o luz de corte", "Anchura de mesa", "Cota de tolerancia"], correct: 0, explanation: "La luz de corte define la altura máxima de la pila de papel que se puede introducir en la máquina.", source: "Examen Oficial FNMT 2022 (Pregunta 33)" },
  { question: "¿Qué elemento protege al operario de astillas o salpicaduras en la zona posterior?", options: ["Las cubiertas y chapa de protección trasera", "El pedal de pre-presión", "El indicador óptico de corte"], correct: 0, explanation: "Los carenados traseros impiden el acceso accidental a los mecanismos móviles de la escuadra y la cuchilla.", source: "Examen Oficial FNMT 2022 (Pregunta 34)" },
  { question: "¿Qué significa el término 'refilado'?", options: ["Corte de igualado o limpieza en los bordes del papel", "Troquelado de esquinas redondeadas", "Afilado de la arista del filo"], correct: 0, explanation: "Refilar consiste en recortar los márgenes de una pila para dejar sus bordes completamente limpios y uniformes.", source: "Examen Oficial FNMT 2022 (Pregunta 35)" },
  { question: "¿Qué ocurre si se acumula polvo de papel sobre la barrera de luz infrarroja?", options: ["Puede provocar bloqueos falsos de la cuchilla por interrupción del haz", "Aumenta la fuerza del pisón", "Acelera el movimiento de la escuadra"], correct: 0, explanation: "La suciedad en los lentes ópticos reduce la transmisión del haz infrarrojo, generando paradas por falsa intrusión.", source: "Examen Oficial FNMT 2022 (Pregunta 36)" },
  { question: "¿Cuál es la función del indicador óptico de corte?", options: ["Proyectar una línea luminosa que indica exactamente dónde caerá la cuchilla", "Iluminar la pantalla de programación", "Indicar el nivel de aceite del depósito"], correct: 0, explanation: "La sombra o línea de luz proyectada sobre el papel marca de forma precisa la línea de caída de la cuchilla.", source: "Examen Oficial FNMT 2022 (Pregunta 37)" },
  { question: "¿Por qué no se debe empujar la pila de papel con la mano cerca de la línea de caída?", options: ["Por riesgo grave de cizallamiento o corte imprevisto", "Porque se ensucia la mesa de soplado", "Porque se borra el programa tecleado"], correct: 0, explanation: "Es una norma fundamental de PRL para evitar amputaciones o atrapamientos en la zona de cizalla.", source: "Examen Oficial FNMT 2022 (Pregunta 38)" },
  { question: "¿Qué herramienta se debe emplear para manipular bloques pequeños cerca del plano de corte?", options: ["Un taco de madereo o empujador de plástico suave", "Pinzas metálicas de presión", "Destornilladores de precisión"], correct: 0, explanation: "El uso del empujador de madera mantiene las manos del operario totalmente fuera del área de peligro de la cuchilla.", source: "Examen Oficial FNMT 2022 (Pregunta 39)" },
  { question: "¿Qué mantenimiento requiere el canal de accionamiento de la escuadra?", options: ["Limpieza de virutas y lubricación periódica del husillo de rosca", "Lavado semanal con agua a presión", "Aplicación de barniz aislante"], correct: 0, explanation: "El husillo que mueve la escuadra debe estar libre de polvo de papel y engrasado para mantener la precisión.", source: "Examen Oficial FNMT 2022 (Pregunta 40)" },

  // 41 - 60 (Tecnología de Artes Gráficas y Soportes)
  { question: "¿Qué se entiende por la dirección de fibra del papel?", options: ["La orientación predominante de las fibras de celulosa formadas durante la fabricación en la máquina continua", "El grosor medio de la hoja", "El grado de blancura del estucado"], correct: 0, explanation: "Las fibras de celulosa se alinean en la dirección de marcha de la máquina de papel durante su formación.", source: "Examen Oficial FNMT 2022 (Pregunta 41)" },
  { question: "¿Por qué es crucial considerar la fibra al cortar pliegos para libros?", options: ["Porque el pliegue debe ser paralelo a la fibra para evitar arrugas o roturas en el lomo", "Porque cambia la velocidad de la cuchilla", "Porque afecta al color de las tintas"], correct: 0, explanation: "Doblar a favor de fibra garantiza un plegado limpio y sin grietas en la espina de los cuadernillos.", source: "Examen Oficial FNMT 2022 (Pregunta 42)" },
  { question: "¿Qué instrumento mide la porosidad o permeabilidad al aire del papel?", options: ["Porosímetro Gurley", "Micrómetro Palmer", "Densitómetro de reflexión"], correct: 0, explanation: "El porosímetro Gurley mide el tiempo que tarda un volumen de aire en atravesar la estructura del papel.", source: "Examen Oficial FNMT 2022 (Pregunta 43)" },
  { question: "¿Cómo se calcula el peso total de un resma de papel sabiendo el gramaje y sus dimensiones?", options: ["Multiplicando la superficie de la hoja (m²) por el gramaje (g/m²) y por 500 hojas", "Dividiendo el espesor entre el número de pliegos", "Sumando el calibre al volumen específico"], correct: 0, explanation: "Una resma contiene 500 pliegos; el peso total se obtiene aplicando la masa por m² al área de los 500 pliegos.", source: "Examen Oficial FNMT 2022 (Pregunta 44)" },
  { question: "¿Qué es el papel estucado o couché?", options: ["Papel recubierto por una capa mineral (ligantes y pigmentos) que mejora la lisura e imprimibilidad", "Papel fabricado 100% con trapos de algodón sin refinar", "Papel sin satinado para periódico"], correct: 0, explanation: "El estuco sella los poros del soporte, permitiendo una gran definición de punto y brillo de tinta.", source: "Examen Oficial FNMT 2022 (Pregunta 45)" },
  { question: "¿Qué humedad relativa óptima debe mantener el taller de corte y estampación?", options: ["Entre 50% y 55% a una temperatura de 20-22 °C", "Entre 10% y 20%", "Superior al 85%"], correct: 0, explanation: "El papel es higroscópico; mantener un ambiente al 50-55% RH evita ondulaciones en los bordes y cambios dimensionales.", source: "Examen Oficial FNMT 2022 (Pregunta 46)" },
  { question: "¿Qué provoca el fenómeno de 'ondulado de bordes' en las pilas de pliegos?", options: ["Absorción de humedad ambiental cuando el papel está más frío o seco que el ambiente del taller", "Uso de cuchillas desafiladas", "Falta de aire en las válvulas de la mesa"], correct: 0, explanation: "Si los bordes de la pila ganan humedad ambiental, se dilatan produciendo deformaciones en olas.", source: "Examen Oficial FNMT 2022 (Pregunta 47)" },
  { question: "¿Qué característica define al papel moneda o de seguridad fabricado por la FNMT?", options: ["Soporte de fibra 100% algodón con marcas de agua, hilos de seguridad y fibrillas fluorescentes", "Papel offset sintético plastificado", "Papel estucado de pasta de madera reciclada"], correct: 0, explanation: "El papel para billetes exige fibra de algodón para máxima resistencia mecánica y la inclusión de elementos antifalsificación.", source: "Examen Oficial FNMT 2022 (Pregunta 48)" },
  { question: "¿Qué mide un espectrofotómetro en el control de calidad gráfica?", options: ["La reflectancia espectral para obtener las coordenadas cromáticas exactas (CIELAB) de una muestra", "El grosor de la lámina de papel", "La viscosidad de la tinta de imprenta"], correct: 0, explanation: "Es el instrumento de referencia para medir color de manera objetiva independiente de la iluminación.", source: "Examen Oficial FNMT 2022 (Pregunta 49)" },
  { question: "¿Qué indica la sigla CIELAB?", options: ["Espacio de color tridimensional definido por las coordenadas L* (luminosidad), a* (eje verde-rojo) y b* (eje azul-amarillo)", "Norma ISO para cuchillas de guillotina", "Unidad de viscosidad de colas industrias"], correct: 0, explanation: "Es el estándar internacional para la medición y comparación cromática objetiva.", source: "Examen Oficial FNMT 2022 (Pregunta 50)" },
  { question: "¿Qué es la ganancia de punto o incremento del valor tonal?", options: ["Aumento del tamaño del punto de trama al transferirse de la forma impresora al soporte", "Disminución del contraste en preimpresión", "Velocidad de secado de las tintas intaglio"], correct: 0, explanation: "La presión de impresión y la absorción del papel provocan que el punto impreso sea mayor que el del archivo original.", source: "Examen Oficial FNMT 2022 (Pregunta 51)" },
  { question: "¿Qué es el sistema de impresión Calcografía o Intaglio utilizado en billetes de banco?", options: ["Impresión en relieve profundo con matrices de acero/cobre que deposita un alto grosor de tinta táctil", "Impresión plana basada en litografía agua-aceite", "Sistema digital por chorro de tinta líquida"], correct: 0, explanation: "La calcografía genera el característico relieve táctil e inconfundible de los documentos de alto valor.", source: "Examen Oficial FNMT 2022 (Pregunta 52)" },
  { question: "¿Qué técnica de impresión se utiliza para fondos de seguridad con guilloches de alta precisión?", options: ["Offset seco o litografía offset de seguridad", "Flexografía con fotopolímeros blandos", "Serigrafía textil manual"], correct: 0, explanation: "El offset de seguridad permite registrar líneas extremadamente finas de varios colores simultáneamente.", source: "Examen Oficial FNMT 2022 (Pregunta 53)" },
  { question: "¿Cuál es la función del elemento OVI (Optical Variable Ink) en billetes y pasaportes?", options: ["Cambiar de color según el ángulo de incidencia de la luz y de observación", "Emitir luz ultravioleta en la oscuridad", "Hacer el papel impermeable al agua"], correct: 0, explanation: "La tinta de variabilidad óptica contiene pigmentos interferenciales que mutan de color al inclinar el documento.", source: "Examen Oficial FNMT 2022 (Pregunta 54)" },
  { question: "¿Qué tipo de trama tipográfica mantiene el tamaño de punto constante pero varía su densidad espacial?", options: ["Trama estocástica o de frecuencia modulada (FM)", "Trama convencional o de amplitud modulada (AM)", "Trama híbrida de líneas redondas"], correct: 0, explanation: "Las tramas FM distribuyen micro-puntos idénticos en posiciones aleatorias, aumentando la resolución visual.", source: "Examen Oficial FNMT 2022 (Pregunta 55)" },
  { question: "¿Qué es el tramado AM o de amplitud modulada?", options: ["Trama donde la distancia entre centros de puntos es fija pero el tamaño del punto varía", "Trama donde los puntos cambian de color aleatoriamente", "Trama de grabado directo a láser"], correct: 0, explanation: "En la trama AM habitual, los puntos crecen en porcentaje de cobertura sobre una retícula fija.", source: "Examen Oficial FNMT 2022 (Pregunta 56)" },
  { question: "¿Qué es la imposición de páginas en preimpresión?", options: ["Distribución ordenada de las páginas de una publicación sobre el pliego para que al plegar queden en secuencia correcta", "Ajuste de tono de las fotografías", "Afilado de las brocas de taladrado"], correct: 0, explanation: "La imposición posiciona las páginas respetando la cascada de plegado de la signatura.", source: "Examen Oficial FNMT 2022 (Pregunta 57)" },
  { question: "¿Qué es el 'sangrado' o 'sangre' en el diseño de un pliego para cortar?", options: ["Extensión del diseño 2 o 3 mm más allá de la línea de corte final para evitar bordes blancos desalineados", "Corte profundo en el cartón", "Un fallo de la bomba hidráulica"], correct: 0, explanation: "La sangre garantiza que, ante pequeñas variaciones mecánicas de corte, no aparezcan fillets o bordes no impresos.", source: "Examen Oficial FNMT 2022 (Pregunta 58)" },
  { question: "¿Qué es la 'calle' en una imposición de pliego?", options: ["El espacio o margen sobrante situado entre los diferentes modelos o páginas impresas", "La anchura total de la guillotina", "El paso del aceite hidráulico"], correct: 0, explanation: "Las calles son los espacios intermedios que permiten aplicar los dos cortes de refilado por cada pieza.", source: "Examen Oficial FNMT 2022 (Pregunta 59)" },
  { question: "¿Qué significa cortar 'a formato final'?", options: ["Dejar el producto a las dimensiones definitivas especificadas cliente eliminando todos los sobrantes", "Cortar la materia prima a mitad de tamaño", "Hacer hendidos sin separar las hojas"], correct: 0, explanation: "Es la operación de refilado definitivo donde se eliminan sangres, marcas de registro y guías.", source: "Examen Oficial FNMT 2022 (Pregunta 60)" },

  // 61 - 80 (Prevención de Riesgos, Normativa y Mantenimiento)
  { question: "Según la Ley 31/1995 de Prevención de Riesgos Laborales, ¿cuál es el objetivo básico de la evaluación de riesgos?", options: ["Identificar y eliminar los peligros en su origen y evaluar los que no hayan podido evitarse", "Sancionar a los trabajadores despistados", "Aumentar el ritmo de producción diaria"], correct: 0, explanation: "La PRL prioriza la eliminación del riesgo en origen antes de aplicar medidas de protección individual o colectiva.", source: "Examen Oficial FNMT 2022 (Pregunta 61)" },
  { question: "¿Qué marcado debe exhibir obligatoriamente toda guillotina industrial comercializada en la UE?", options: ["Marcado CE con su correspondiente declaración de conformidad", "Sello de calidad voluntario", "Etiqueta verde ecolatina"], correct: 0, explanation: "El marcado CE atestigua que la maquinaria cumple las directivas de seguridad comunitarias aplicables.", source: "Examen Oficial FNMT 2022 (Pregunta 62)" },
  { question: "¿Con qué frecuencia se deben revisar los dispositivos de seguridad de parada de emergencia en talleres?", options: ["Diariamente antes del comienzo de cada turno o trabajo", "Una vez al año por el fabricante", "Únicamente cuando se averíen"], correct: 0, explanation: "El operario debe verificar el correcto funcionamiento de paradas de emergencia y células fotosensibles cada día.", source: "Examen Oficial FNMT 2022 (Pregunta 63)" },
  { question: "¿Qué EPI es indispensable al manipular y cambiar la cuchilla de la guillotina?", options: ["Guantes anticorte de malla o fibra de alta resistencia y calzado de seguridad", "Guantes de látex desechables", "Mascarilla de filtro de carbón activo"], correct: 0, explanation: "El cambio de cuchilla exige guantes certificados contra cizallamiento e impactos por caída.", source: "Examen Oficial FNMT 2022 (Pregunta 64)" },
  { question: "Durante el cambio de cuchilla, ¿qué utilaje específico se debe atornillar al cuerpo de la cuchilla?", options: ["Los empuñadores o soportes de manipulación con rosca de fijación", "Una llave inglesa pesada", "Un gato hidráulico portátil"], correct: 0, explanation: "Los varillajes de sujeción roscados permiten extraer y transportar la cuchilla pesada sin tocar el filo directo.", source: "Examen Oficial FNMT 2022 (Pregunta 65)" },
  { question: "¿Qué categoría de nivel de ruido continuo equivalente (LAeq) exige el uso obligatorio de protectores auditivos?", options: ["A partir de 85 dB(A)", "A partir de 60 dB(A)", "A partir de 110 dB(A) exclusivamente"], correct: 0, explanation: "A partir de 85 dB(A) la legislación española exige el uso efectivo de EPIs auditivos (tapones o cascos).", source: "Examen Oficial FNMT 2022 (Pregunta 66)" },
  { question: "¿Qué tipo de extintor es adecuado para un fuego eléctrico en el cuadro de control de la máquina?", options: ["Extintor de Nieve Carbónica (CO2)", "Extintor de agua a chorro", "Manguera de agua con espuma vegetal"], correct: 0, explanation: "El CO2 es un agente diエルéctrico que no deja residuos ni daña los circuitos electrónicos de la máquina.", source: "Examen Oficial FNMT 2022 (Pregunta 67)" },
  { question: "En prevención de riesgos, ¿qué clase de medida tiene prioridad sobre la protección individual?", options: ["La protección colectiva (barreras, resguardos, extracción centralizada)", "La formación teórica", "Los carteles de advertencia"], correct: 0, explanation: "La protección colectiva prevalece siempre sobre el equipo de protección individual (EPI).", source: "Examen Oficial FNMT 2022 (Pregunta 68)" },
  { question: "¿Qué riesgo principal se deriva de un nivel inadecuado de iluminación en el puesto de corte?", options: ["Fatiga visual y aumento de la probabilidad de errores o accidentes mecánicos", "Rotura prematura de la cuchilla", "Descalibración de la pantalla"], correct: 0, explanation: "Una iluminación defectuosa dificulta la visión de los trazados de corte y fatiga la vista del operario.", source: "Examen Oficial FNMT 2022 (Pregunta 69)" },
  { question: "¿Qué se debe hacer antes de realizar cualquier intervención técnica dentro del cuadro eléctrico?", options: ["Consignación o bloqueo LOTO (Lock Out, Tag Out) e interrupción total de energía", "Bajar únicamente el pisón", "Limpiar la pantalla con un paño seco"], correct: 0, explanation: "El procedimiento LOTO garantiza que nadie pueda reconectar la corriente de forma accidental durante la reparación.", source: "Examen Oficial FNMT 2022 (Pregunta 70)" },
  { question: "¿Qué tipo de residuos son las latas de tinta y trapos impregnados de disolvente?", options: ["Residuos peligrosos tóxicos o inflamables que requieren gestor autorizado", "Residuos urbanos orgánicos", "Residuos inertes comparables a papel"], correct: 0, explanation: "Los restos de productos químicos de imprenta deben depositarse en contenedores cerrados y gestionarse formalmente.", source: "Examen Oficial FNMT 2022 (Pregunta 71)" },
  { question: "¿Qué norma ISO establece los requisitos para un Sistema de Gestión Ambiental en la industria?", options: ["ISO 14001", "ISO 9001", "ISO 27001"], correct: 0, explanation: "La norma ISO 14001 define los estándares internacionales para la gestión ambiental en procesos productivos.", source: "Examen Oficial FNMT 2022 (Pregunta 72)" },
  { question: "¿Qué norma ISO regula la Gestión de la Calidad?", options: ["ISO 9001", "ISO 14001", "ISO 45001"], correct: 0, explanation: "La norma ISO 9001 establece los criterios para implantar sistemas eficaces de control de calidad.", source: "Examen Oficial FNMT 2022 (Pregunta 73)" },
  { question: "¿Qué norma ISO especifica las condiciones de impresión Offset y control de color?", options: ["ISO 12647", "ISO 216", "ISO 9000"], correct: 0, explanation: "La serie ISO 12647 estandariza la separación de color, confección de formas e impresión offset.", source: "Examen Oficial FNMT 2022 (Pregunta 74)" },
  { question: "¿Qué formato estandarizado por la norma ISO 216 equivale a 210 x 297 mm?", options: ["A4", "A3", "A5"], correct: 0, explanation: "El formato A4 es la medida base internacional con dimensiones exactas de 210 x 297 mm.", source: "Examen Oficial FNMT 2022 (Pregunta 75)" },
  { question: "¿Qué relación dimensional guarda la serie A de formatos de papel conforme a la ISO 216?", options: ["Relación 1 : √2 (1 a raíz cuadrada de 2)", "Relación 1 : 1,5", "Relación 1 : 2 exactos"], correct: 0, explanation: "La relación 1 : √2 permite doblar por la mitad una hoja manteniendo la misma proporción geométrica.", source: "Examen Oficial FNMT 2022 (Pregunta 76)" },
  { question: "¿Qué superficie exacta abarca un pliego de formato A0?", options: ["1 metro cuadrado (1 m²)", "0,5 metros cuadrados", "2 metros cuadrados"], correct: 0, explanation: "El formato A0 se define con las medidas 841 x 1189 mm, lo que equivale exactamente a un área de 1 m².", source: "Examen Oficial FNMT 2022 (Pregunta 77)" },
  { question: "¿Cuántos pliegos de tamaño A4 se obtienen cortando un pliego base A0 sin mermas?", options: ["16 pliegos A4", "8 pliegos A4", "32 pliegos A4"], correct: 0, explanation: "A0 = 2 A1 = 4 A2 = 8 A3 = 16 pliegos A4.", source: "Examen Oficial FNMT 2022 (Pregunta 78)" },
  { question: "¿Qué es el gramaje estándar comercial del papel offset de fotocopia común?", options: ["80 g/m²", "135 g/m²", "300 g/m²"], correct: 0, explanation: "El papel estándar de oficina o reprografía común presenta un gramaje de 80 gramos por metro cuadrado.", source: "Examen Oficial FNMT 2022 (Pregunta 79)" },
  { question: "¿Qué máquina se emplea en acabados para realizar hendidos o surcos en cartulinas antes de plegar?", options: ["Hendidora o troqueladora", "Guillotina trilateral", "Grapadora de alambre continua"], correct: 0, explanation: "El hendido debilita la fibra de cartulinas gruesas para permitir un pliegue limpio sin roturas en el estuco.", source: "Examen Oficial FNMT 2022 (Pregunta 80)" },

  // 81 - 100 (Matemáticas aplicadas, Geometría de pliegos y Acabados)
  { question: "¿Cuántos cortes sencillos se requieren para separar una tira de papel en 5 piezas iguales?", options: ["4 cortes", "5 cortes", "3 cortes"], correct: 0, explanation: "Para dividir un elemento continuo en N partes lineales idénticas se realizan siempre N - 1 cortes.", source: "Examen Oficial FNMT 2022 (Pregunta 81)" },
  { question: "Si un pliego mide 700 x 1000 mm, ¿cuántas tarjetas de 100 x 70 mm caben teóricamente sin contar calles?", options: ["100 tarjetas", "70 tarjetas", "50 tarjetas"], correct: 0, explanation: "(700/70) = 10 y (1000/100) = 10; multiplicando 10 x 10 = 100 tarjetas exactas.", source: "Examen Oficial FNMT 2022 (Pregunta 82)" },
  { question: "De un pliego de 650 x 900 mm se quieren cortar piezas de 200 x 300 mm. ¿Cuál es el aprovechamiento máximo por pliego?", options: ["9 piezas", "6 piezas", "12 piezas"], correct: 0, explanation: "En horizontal (650/200=3) x (900/300=3) = 9 piezas. Disposición óptima.", source: "Examen Oficial FNMT 2022 (Pregunta 83)" },
  { question: "Si aplicamos una merma de impresión y corte del 5% para un trabajo de 10.000 folletos, ¿cuántos folletos debemos planificar en entrada?", options: ["10.526 folletos (o aproximadamente 10.500 bruto)", "10.050 folletos", "9.500 folletos"], correct: 0, explanation: "Para obtener 10.000 netos con un 5% de pérdida sobre el total bruto: 10.000 / 0.95 = 10.526 pliegos.", source: "Examen Oficial FNMT 2022 (Pregunta 84)" },
  { question: "¿Qué máquina realiza el corte simultáneo de tres cantos (cabeza, pie y frente) en libros o cuadernos?", options: ["Guillotina trilateral", "Guillotina monocuchilla", "Cizalladora rotativa"], correct: 0, explanation: "La trilateral dispone de tres cuchillas dispuestas en U para refilar los tres lados del libro en un solo ciclo.", source: "Examen Oficial FNMT 2022 (Pregunta 85)" },
  { question: "¿Qué tipo de encuadernación une las hojas mediante cola termoplástica (Hot-Melt o PUR) tras fresar el lomo?", options: ["Encuadernación rústica fresada o pegada", "Encuadernación cosida con hilo textil", "Encuadernación de espiral metálica"], correct: 0, explanation: "El fresado crea canales en las hojas para que la cola penetre sujetando el bloque de hojas sueltas.", source: "Examen Oficial FNMT 2022 (Pregunta 86)" },
  { question: "¿Qué ventaja principal ofrece el adhesivo PUR frente al Hot-Melt convencional?", options: ["Gran flexibilidad, resistencia a disolventes y mayor fuerza de pegado en papeles estucados o barnizados", "Secado instantáneo en 0,1 segundos", "Menor coste económico"], correct: 0, explanation: "El adhesivo de poliuretano reactivo (PUR) forma enlaces químicos que no se destruyen con la temperatura ni aceites.", source: "Examen Oficial FNMT 2022 (Pregunta 87)" },
  { question: "¿Qué es una 'signatura' en encuadernación?", options: ["El conjunto de páginas impresas en un pliego que, tras ser plegado, forma un cuadernillo", "La firma del autor en la portada", "El certificado de calidad de la bobina"], correct: 0, explanation: "Las signaturas son los cuadernillos individuales (de 8, 16 o 32 páginas) que forman el cuerpo del libro.", source: "Examen Oficial FNMT 2022 (Pregunta 88)" },
  { question: "¿Qué operación sigue al embuchado o alzado de signaturas en encuadernación rústica cosida?", options: ["Cosido con hilo de algodón/sintético y encolado de lomo", "Plastificado brillante de la tripa", "Guillotinado individual pliego a pliego"], correct: 0, explanation: "Tras formar el cuerpo ordenado de cuadernillos, la cosedora de hilo cose cada signatura antes de encolar.", source: "Examen Oficial FNMT 2022 (Pregunta 89)" },
  { question: "¿Qué se entiende por 'alzado' de pliegos?", options: ["Colocar las signaturas o pliegos impresos de forma correlativa uno encima de otro para formar la tripa del libro", "Elevar la mesa hidráulica de la guillotina", "Aumentar el brillo de la tinta"], correct: 0, explanation: "El alzado es la secuencia de superposición ordenada de los cuadernillos de la obra.", source: "Examen Oficial FNMT 2022 (Pregunta 90)" },
  { question: "¿Qué se entiende por 'embuchado'?", options: ["Insertar unas signaturas dentro de otras formando un conjunto anidado (típico de revistas grapadas)", "Meter los pliegos dentro de la funda de plástico", "Mezclar tintas de color en la batidora"], correct: 0, explanation: "El embuchado mete cuadernillos unos dentro de otros para grapados a lomo (cosido a caballete).", source: "Examen Oficial FNMT 2022 (Pregunta 91)" },
  { question: "¿Qué accesorio de la guillotina elimina las cargas electrostáticas acumuladas durante el movimiento de los pliegos?", options: ["Las barras ionizadoras o deselectrizadoras neumáticas", "El pedal de comprobación", "El depósito de aceite oleohidráulico"], correct: 0, explanation: "Las barras ionizadoras neutralizan la carga estática que hace que las hojas de plástico o papel se peguen.", source: "Examen Oficial FNMT 2022 (Pregunta 92)" },
  { question: "En el refilado de productos impresos en plástico o sintéticos, ¿qué problema surge por la fricción?", options: ["Calentamiento y fusión de los bordes del material por la fricción de la cuchilla", "Exceso de absorción de aceite", "Desalineación de la pantalla táctil"], correct: 0, explanation: "La fricción rápida del acero genera calor local que funde bordes de polipropileno o PVC si el filo no está perfecto.", source: "Examen Oficial FNMT 2022 (Pregunta 93)" },
  { question: "¿Qué tipo de cuchilla minimiza la fricción térmica al cortar plástico sintético?", options: ["Cuchillas con recubrimiento de Teflón (PTFE) o pulido espejo fino", "Cuchillas de acero dulce al carbono", "Cuchillas con muescas dentadas"], correct: 0, explanation: "El tratamiento antiadherente de teflón reduce drásticamente el rozamiento y la acumulación de resinas.", source: "Examen Oficial FNMT 2022 (Pregunta 94)" },
  { question: "¿Cómo se llama el plano de trabajo de la guillotina donde reposa la pila de papel?", options: ["Mesa de corte o bancada", "Chasis neumático", "Bastidor superior"], correct: 0, explanation: "La mesa de corte de acero rectificado o cromado soporta el papel y alberga los canales de soplado e impacto.", source: "Examen Oficial FNMT 2022 (Pregunta 95)" },
  { question: "¿Qué función cumple el visor o lupa sobre la escala de la escuadra en máquinas manuales/semiautomáticas?", options: ["Permitir la lectura precisa de la cota con precisión de milímetros o fracciones", "Aumentar el tamaño del texto del programa", "Iluminar la zona de pisón"], correct: 0, explanation: "La óptica de aumento evita errores de paralaje al ajustar la medida de la escuadra manualmente.", source: "Examen Oficial FNMT 2022 (Pregunta 96)" },
  { question: "¿Qué es la 'suela del pisón'?", options: ["La superficie inferior plana del bloque de prensado que contacta directamente con el papel", "La base de goma de la máquina sobre el suelo", "El listón plástico de impacto"], correct: 0, explanation: "La suela ejerce la fuerza de compactación uniforme sobre la parte superior de la pila.", source: "Examen Oficial FNMT 2022 (Pregunta 97)" },
  { question: "¿Por qué se utiliza aire comprimido secado y filtrado en los sistemas neumáticos de guillotinas?", options: ["Para evitar la condensación de agua y aceite que mancharía el papel y oxidaría las válvulas", "Para aumentar el volumen de la mesa", "Para no hacer ruido durante el soplado"], correct: 0, explanation: "El agua o aceite en el circuito neumático destruye pliegos impresos y bloquea las microbolas de la mesa.", source: "Examen Oficial FNMT 2022 (Pregunta 98)" },
  { question: "¿Cuál es el principal beneficio del mantenimiento predictivo en líneas automatizadas de corte?", options: ["Detectar anomalías antes de que provoquen averías graves o paradas no programadas", "Reducir el consumo de papel al 50%", "Eliminar la necesidad de operarios cualificados"], correct: 0, explanation: "Monitorizar vibraciones, temperatura de aceite y estado del filo previene fallos catastróficos.", source: "Examen Oficial FNMT 2022 (Pregunta 99)" },
  { question: "En el contexto de la FNMT, ¿qué se exige a los operarios en cuanto a confidencialidad y custodia de materiales de desperdicio?", options: ["Recuento, custodia y destrucción controlada estricta de todo el maculatura y virutas impresas de valor", "Tirar el papel sobrante a contenedores de calle", "Regalar los recortes sobrantes a personal ajeno"], correct: 0, explanation: "Todo residuo impreso o viruta de papel de seguridad debe ser contabilizado y destruido en trituradoras bajo estricta supervisión.", source: "Examen Oficial FNMT 2022 (Pregunta 100)" }
];


  


