const examFNMT2023 = [
  
/* ========================================================
   BANCO OFICIAL - EXAMEN FNMT 2023 (100 PREGUNTAS)
   ======================================================== */

//const examFNMT2023 = [
  { question: "En la programación POLAR, ¿qué presión de prensado se exige para el corte de papel de etiquetas?", options: ["3.500 - 4.000 daN", "1.500 - 2.000 daN", "800 - 1.000 daN"], correct: 0, explanation: "Por la densidad y resistencia del papel para etiquetas, el ajuste hidráulico debe situarse entre 3.500 y 4.000 daN.", source: "Examen FNMT 2023 (Pregunta 1)" },
  { question: "Para fijar la posición de una medida teórica introducida en POLAR X / XT, ¿qué acción valida el movimiento?", options: ["Pulsar 2 veces la tecla '=' o presionar la tecla táctil 'Liberar función'", "Pulsar 1 vez la tecla '0'", "Accionar el pedal de pre-presión"], correct: 0, explanation: "Es la secuencia estándar en el panel para habilitar el desplazamiento motorizado de la escuadra a la nueva cota.", source: "Examen FNMT 2023 (Pregunta 2)" },
  { question: "¿Qué función cumple la válvula de bolas neumáticas en la mesa de soplado de la guillotina?", options: ["Crear una almohadilla de aire al hundirse por el peso de la pila de papel", "Elevar la presión del fluido hidráulico del pisón", "Regular la bajada de la cuchilla"], correct: 0, explanation: "Al colocar el papel sobre la mesa, las bolas se presionan hacia abajo abriendo el paso de aire comprimido para flotar la pila.", source: "Examen FNMT 2023 (Pregunta 3)" },
  { question: "¿A qué equivalencia exacta corresponde 1 decanewton (daN) en el Sistema Internacional?", options: ["10 Newtons", "100 Newtons", "1 Newton"], correct: 0, explanation: "El decanewton (daN) equivale exactamente a 10 Newtons.", source: "Examen FNMT 2023 (Pregunta 4)" },
  { question: "Para evitar marcas o aplastamiento al prensar papeles gofrados o con relieve, ¿qué elemento se acopla?", options: ["Una suela o placa de recubrimiento flexible para el pisón", "Un suplemento de acero estriado", "Un chorro directo de lubricante seco"], correct: 0, explanation: "La placa elástica bajo la suela amortigua el contacto directo, distribuyendo la presión sobre la textura del papel.", source: "Examen FNMT 2023 (Pregunta 5)" },
  { question: "¿Qué tipo de cuchilla ofrece la máxima resistencia al corte de papeles abrasivos o de alta carga mineral?", options: ["Cuchilla con encastre de metal duro (carburo de tungsteno / Widia)", "Cuchilla de acero al carbono común", "Cuchilla de aleación de aluminio"], correct: 0, explanation: "Las cuchillas de carburo de tungsteno soportan la abrasión mineral de los papeles reduciendo la frecuencia de afilado.", source: "Examen FNMT 2023 (Pregunta 6)" },
  { question: "¿Cuál es el riesgo de emplear una cuchilla de Widia al cortar pliegos con grapas o alambres?", options: ["Desportillado o fractura de la plaquita por choque directo", "Oxidación instantánea de la masa de acero", "Fallo neumático en la mesa de soplado"], correct: 0, explanation: "El carburo de tungsteno tiene una gran dureza pero es quebradizo ante golpes secos contra objetos metálicos.", source: "Examen FNMT 2023 (Pregunta 7)" },
  { question: "¿Qué se entiende por 'luz de corte' en una guillotina industrial?", options: ["La anchura máxima y apertura de paso disponible para introducir la pila", "La potencia del foco de iluminación", "La tolerancia de error de la escuadra"], correct: 0, explanation: "Define las dimensiones máximas en ancho y altura que la guillotina puede admitir en su zona de trabajo.", source: "Examen FNMT 2023 (Pregunta 8)" },
  { question: "¿Qué componente electrónico interrumpe el descenso de la cuchilla si el operario introduce las manos?", options: ["La cortina infrarroja o barrera fotoeléctrica", "El codificador del motor principal", "El relé de presión del hidráulico"], correct: 0, explanation: "La barrera óptica detecta la interrupción de los haces infrarrojos bloqueando el embrague inmediatamente.", source: "Examen FNMT 2023 (Pregunta 9)" },
  { question: "En la POLAR 115, ¿cuál es la fuerza máxima autorizada sobre el pedal mecánico de verificación?", options: ["300 N", "500 N", "1.000 N"], correct: 0, explanation: "Para evitar lesiones durante la comprobación visual del trazado, la fuerza sobre el pedal se limita a 300 N.", source: "Examen FNMT 2023 (Pregunta 10)" },
  { question: "¿Qué función tiene el programa de corte 'AutoTrim'?", options: ["Apertura neumática de la mesa para desechar automáticamente las tiras de refilado", "Afilado guiado por láser", "Control de humedad en la entrada"], correct: 0, explanation: "AutoTrim abre un segmento de la mesa para evacuar virutas y recortes sin que el maquinista use las manos.", source: "Examen FNMT 2023 (Pregunta 11)" },
  { question: "¿Qué sucede cuando se aplica una presión del pisón inferior a la requerida por la pila?", options: ["Desplazamiento de los pliegos inferiores hacia fuera (corte en seta)", "Aumento de la temperatura de la cuchilla", "Bloqueo del motor hidráulico"], correct: 0, explanation: "Si la sujeción es insuficiente, la resistencia del corte empuja las hojas de abajo generando deformación en seta.", source: "Examen FNMT 2023 (Pregunta 12)" },
  { question: "¿Qué ajuste mecánico se exige tras montar una cuchilla que ha sido reafilada?", options: ["Regulación del punto de parada inferior mediante la excéntrica de ajuste", "Sustitución de la bomba hidráulica", "Calibración del brillo de pantalla"], correct: 0, explanation: "Debido a la pérdida de altura por el afilado, debe ajustarse el tope inferior para marcar suavemente el listón.", source: "Examen FNMT 2023 (Pregunta 13)" },
  { question: "¿Cuántos cantos útiles de impacto posee un listón sintético de sección cuadrada?", options: ["8 posiciones distintas", "4 posiciones distintas", "2 posiciones distintas"], correct: 0, explanation: "Al ser cuadrado simétrico, cada cara ofrece 2 cantos de corte al dársele la vuelta (2 x 4 = 8).", source: "Examen FNMT 2023 (Pregunta 14)" },
  { question: "¿Qué tolerancia dimensional garantiza una guillotina calibrada para documentos de alta seguridad?", options: ["±0,1 mm", "±1,0 mm", "±2,0 mm"], correct: 0, explanation: "El acabado de documentos de valor o billetes exige un margen de variación que no exceda de una décima de milímetro.", source: "Examen FNMT 2023 (Pregunta 15)" },
  { question: "¿Cuál es la causa principal del sobrecalentamiento en el circuito hidráulico durante la jornada?", options: ["Filtros de aceite obstruidos o nivel de fluido por debajo del mínimo recomendado", "Uso prolongado de la mesa de aire", "Plegado incorrecto del papel"], correct: 0, explanation: "Un nivel bajo o filtros sucios dificultan la circulación del fluido oleohidráulico, elevando la temperatura.", source: "Examen FNMT 2023 (Pregunta 16)" },
  { question: "¿Qué indica la 'cota de retestado' en la secuencia de programación de un pliego?", options: ["La dimensión del corte perimetral de limpieza inicial para escuadrar el pliego", "La distancia desde la escuadra a la pantalla", "El espesor del cartón"], correct: 0, explanation: "El retestado es el primer refilado (1 a 3 mm) para eliminar las imperfecciones de los bordes brutos.", source: "Examen FNMT 2023 (Pregunta 17)" },
  { question: "¿Cómo se previene el frotamiento y desgaste en los bordes de papeles poco deslizantes?", options: ["Cargando el papel arrimado hacia el lado izquierdo de la mesa", "Arrimando el papel a la regla derecha", "Aumentando la fuerza del pisón"], correct: 0, explanation: "Colocar la pila a la izquierda evita la fricción continua contra la guía fija de la derecha.", source: "Examen FNMT 2023 (Pregunta 18)" },
  { question: "¿Qué característica de la cuchilla se debe modificar para cortar cartón duro de alta densidad?", options: ["Aumentar el ángulo del bisel (bisel doble de 24° a 26°)", "Reducir el grosor de la lámina de acero", "Usar una arista mellada"], correct: 0, explanation: "Un bisel mayor da cuerpo y resistencia metálica a la arista, evitando deformaciones frente al cartón.", source: "Examen FNMT 2023 (Pregunta 19)" },
  { question: "En materia de prevención, ¿qué acción debe detener la cuchilla instantáneamente?", options: ["Liberar cualquiera de los dos mandos del accionamiento bimanual", "Apretar el pedal de pre-presión", "Encender la luz de trabajo"], correct: 0, explanation: "El sistema bimanual requiere ambas manos ocupadas; si una se retira, la carrera de corte se frena de inmediato.", source: "Examen FNMT 2023 (Pregunta 20)" },
  { question: "¿Qué se entiende por la dirección de la fibra del papel?", options: ["La orientación longitudinal que adoptan las fibras de celulosa durante la fabricación", "El espesor de la hoja", "El color de la pasta de madera"], correct: 0, explanation: "En la máquina continua, la suspensión de celulosa orienta sus fibras en la dirección de la marcha.", source: "Examen FNMT 2023 (Pregunta 21)" },
  { question: "¿Por qué es importante cortar el papel manteniendo la fibra paralela al lomo en encuadernación?", options: ["Para facilitar el plegado sin romper ni agrietar la superficie del papel", "Para que la guillotina corte más rápido", "Para reducir el gasto de tinta"], correct: 0, explanation: "Plegar a favor de fibra evita que la celulosa se quebrante o genere arrugas en el lomo de la obra.", source: "Examen FNMT 2023 (Pregunta 22)" },
  { question: "¿Qué mide el ensayador Gurley en las pruebas de laboratorio de papel?", options: ["La porosidad o permeabilidad al aire de la hoja", "La resistencia al reventamiento", "El brillo de la superficie"], correct: 0, explanation: "El porosímetro Gurley calcula el tiempo en segundos que tarda un volumen de aire en atravesar el papel.", source: "Examen FNMT 2023 (Pregunta 23)" },
  { question: "¿Cómo se define el gramaje de un soporte papelero?", options: ["La masa en gramos de una hoja de un metro cuadrado de superficie (g/m²)", "El grosor medido en micras", "El volumen total por resma"], correct: 0, explanation: "El gramaje expresa la relación entre el peso en gramos y la superficie de un metro cuadrado.", source: "Examen FNMT 2023 (Pregunta 24)" },
  { question: "¿Con qué instrumento se mide con precisión el espesor o calibre de una hoja?", options: ["Micrómetro o Palmer de platillos", "Espectrofotómetro de esfera", "Densitómetro de transmisión"], correct: 0, explanation: "El micrómetro mide en micras (µm) la distancia entre las dos caras de la hoja de papel.", source: "Examen FNMT 2023 (Pregunta 25)" },
  { question: "¿Qué es el papel estucado?", options: ["Papel recubierto por una salsa mineral que mejora la lisura y la definición del punto impreso", "Papel fabricado sin pulpa de madera", "Papel de envolver rugoso"], correct: 0, explanation: "La capa de estuco sella la porosidad del papel permitiendo impresiones de alta calidad.", source: "Examen FNMT 2023 (Pregunta 26)" },
  { question: "¿Qué ocurre si la humedad relativa del taller cae por debajo del 40%?", options: ["Aumento de la carga electrostática y peligro de deformación por secado", "Condensación en la mesa de aire", "Desplazamiento automático de la escuadra"], correct: 0, explanation: "El ambiente seco elimina la humedad del papel, acumulando estática y combando las esquinas.", source: "Examen FNMT 2023 (Pregunta 27)" },
  { question: "¿Qué composición tiene el papel utilizado por la FNMT para la fabricación de billetes?", options: ["100% fibras de algodón con marca de agua e hilos de seguridad", "100% pasta química de madera reciclada", "Soporte polimérico sin fibras"], correct: 0, explanation: "El papel moneda exige pasta de algodón para soportar arrugas, plegados y adherir elementos de seguridad.", source: "Examen FNMT 2023 (Pregunta 28)" },
  { question: "¿Qué mide el espectrofotómetro en las pruebas de color?", options: ["La reflectancia espectral para calcular coordenadas colorimétricas objetivas (CIELAB)", "La densidad óptica de la tinta negra", "El porcentaje de humedad"], correct: 0, explanation: "Mide la luz reflejada en todo el espectro visible para caracterizar matemáticamente el color.", source: "Examen FNMT 2023 (Pregunta 29)" },
  { question: "En el sistema CIELAB, ¿qué representa el eje a*?", options: ["La posición del color entre el verde (valores negativos) y el rojo (valores positivos)", "La luminosidad total", "El eje azul-amarillo"], correct: 0, explanation: "El eje a* define los tonos entre verde y rojo, mientras que el b* define azul y amarillo.", source: "Examen FNMT 2023 (Pregunta 30)" },
  { question: "¿Qué es la ganancia de punto de trama?", options: ["El aumento de tamaño que experimenta el punto impreso respecto al valor original del archivo", "El brillo de la tinta en el secado", "La separación de la línea de corte"], correct: 0, explanation: "La presión del cilindro y la penetración de la tinta hacen que el punto crezca en la impresión real.", source: "Examen FNMT 2023 (Pregunta 31)" },
  { question: "¿Qué caracteriza al proceso de impresión Calcográfico (Intaglio)?", options: ["Uso de matrices grabadas en profundidad que depositan una capa gruesa de tinta con relieve táctil", "Impresión plana sin presión", "Inyección térmica de tinta"], correct: 0, explanation: "Es el sistema de seguridad que genera el relieve perceptible al tacto en billetes y pasaportes.", source: "Examen FNMT 2023 (Pregunta 32)" },
  { question: "¿Qué es el Offset de seguridad?", options: ["Impresión litográfica de alta precisión para fondos de guilloches sin variación de registro", "Impresión en prensas digitales de oficina", "Serigrafía de alta velocidad"], correct: 0, explanation: "Permite imprimir tramas de líneas finas continuas combinando varios colores simultáneamente.", source: "Examen FNMT 2023 (Pregunta 33)" },
  { question: "¿Qué propiedad tiene la tinta ópticamente variable (OVI)?", options: ["Cambiar de color según el ángulo desde el que se observa el documento", "Brillar bajo la luz solar únicamente", "Borrarse con el calor de las manos"], correct: 0, explanation: "Contiene pigmentos de interferencia que cambian de tonalidad (p. ej. de verde a magenta) al inclinarlo.", source: "Examen FNMT 2023 (Pregunta 34)" },
  { question: "¿Qué es la trama de amplitud modulada (AM)?", options: ["Trama convencional con distancia fija entre puntos y variación en el tamaño de los mismos", "Trama de puntos aleatorios idénticos", "Trama de grabado láser"], correct: 0, explanation: "En la trama AM clásica, el porcentaje de tono depende de lo grande que sea el punto.", source: "Examen FNMT 2023 (Pregunta 35)" },
  { question: "¿Qué es la trama de frecuencia modulada (FM o estocástica)?", options: ["Trama con puntos de tamaño micro fijo distribuidos con mayor o menor densidad", "Trama de líneas continuas paralelas", "Trama de flexografía"], correct: 0, explanation: "Mantiene el tamaño de punto constante y varía la cantidad de puntos por unidad de superficie.", source: "Examen FNMT 2023 (Pregunta 36)" },
  { question: "¿Qué se realiza en la fase de imposición digital de pliegos?", options: ["Disponer las páginas en el orden y orientación adecuados para su correcto plegado posterior", "Verificar la presión de la guillotina", "Regular la viscosidad de la tinta"], correct: 0, explanation: "Coloca las páginas en la hoja de máquina para que tras el plegado queden en orden numérico.", source: "Examen FNMT 2023 (Pregunta 37)" },
  { question: "¿Qué es la 'sangre' o 'sangrado' de un documento?", options: ["La zona de la imagen que sobrepasa la línea de corte para evitar filos blancos al refilar", "Un defecto de impresión por exceso de agua", "La sombra proyectada por el pisón"], correct: 0, explanation: "Se añaden 2 o 3 mm de diseño hacia fuera para compensar las ligeras tolerancias de corte.", source: "Examen FNMT 2023 (Pregunta 38)" },
  { question: "¿Qué es la 'calle' en la distribución de páginas de un pliego?", options: ["El margen sobrante que separa dos elementos o páginas contiguas en el pliego", "La distancia de seguridad del operario", "El canal de avance del carro"], correct: 0, explanation: "Es el espacio blanco entre dos impresos que permite aplicar dos cortes de refilado independientes.", source: "Examen FNMT 2023 (Pregunta 39)" },
  { question: "¿Qué significa refilar un bloque 'a formato final'?", options: ["Realizar los cortes definitivos que dejan el producto a las dimensiones exactas especificadas", "Cortar el pliego por la mitad para transporte", "Hacer marcas de hendido en el lomo"], correct: 0, explanation: "Es la operación donde se eliminan sangrados, escalas de color y marcas de registro.", source: "Examen FNMT 2023 (Pregunta 40)" },
  { question: "Según la Ley de Prevención de Riesgos Laborales, ¿cuál es la primera prioridad preventiva?", options: ["Evitar los riesgos y combatir los que no se hayan podido evitar en su origen", "Repartir equipos de protección individual", "Instalar carteles de aviso"], correct: 0, explanation: "La ley antepone siempre la eliminación del riesgo en la fuente antes que la protección del trabajador.", source: "Examen FNMT 2023 (Pregunta 41)" },
  { question: "¿Qué demuestra el marcado CE en una guillotina industrial?", options: ["Que la máquina cumple con todas las Directivas de Seguridad Europeas obligatorias", "Que ha sido fabricada en Alemania", "Que tiene garantía comercial de por vida"], correct: 0, explanation: "El marcado CE es la declaración legal de cumplimiento con las normas europeas de seguridad.", source: "Examen FNMT 2023 (Pregunta 42)" },
  { question: "¿Con qué periodicidad debe comprobarse el funcionamiento del paro de emergencia?", options: ["Al inicio de cada jornada o turno de trabajo", "Una vez al mes por mantenimiento", "Solo si la máquina falla"], correct: 0, explanation: "Es una obligación de seguridad diaria verificar que la parada de emergencia detiene la máquina.", source: "Examen FNMT 2023 (Pregunta 43)" },
  { question: "¿Qué EPI es indispensable para manipular o transportar la cuchilla de la guillotina?", options: ["Guantes certificados contra cortes e impactos y calzado de seguridad", "Guantes finos de goma", "Gafas de sol polarizadas"], correct: 0, explanation: "El filo extremadamente agudo de la cuchilla exige guantes de malla o fibra resistente a cizallamientos.", source: "Examen FNMT 2023 (Pregunta 44)" },
  { question: "¿Qué accesorio técnico se rosca a la cuchilla para extraerla de forma segura?", options: ["Los empuñadores o varillas de sujeción roscadas", "Una llave fija de estrella", "Un alicate de presión"], correct: 0, explanation: "Las varillas permiten sujetar la cuchilla con firmeza manteniendo las manos alejadas del filo.", source: "Examen FNMT 2023 (Pregunta 45)" },
  { question: "¿A partir de qué nivel de ruido equivalente (LAeq) es obligatorio usar protectores auditivos?", options: ["85 dB(A)", "65 dB(A)", "100 dB(A)"], correct: 0, explanation: "El Real Decreto 286/2006 fija el límite de acción superior en 85 dB(A) para el uso obligatorio de EPIs auditivos.", source: "Examen FNMT 2023 (Pregunta 46)" },
  { question: "¿Qué extintor se debe utilizar si se produce un fuego en el cuadro electrónico de la máquina?", options: ["Extintor de dióxido de carbono (CO2)", "Extintor de agua pulverizada", "Manguera de espuma vegetal"], correct: 0, explanation: "El CO2 es un gas dieléctrico que sofoca el fuego sin conducir la electricidad ni dañar los circuitos.", source: "Examen FNMT 2023 (Pregunta 47)" },
  { question: "En seguridad laboral, ¿por qué la protección colectiva prima sobre el EPI individual?", options: ["Porque protege a todos los trabajadores expuestos simultáneamente e independientemente de su actitud", "Porque es más barata de instalar", "Porque no requiere mantenimiento"], correct: 0, explanation: "Los resguardos colectivos evitan el peligro directamente para cualquier persona que se acerque.", source: "Examen FNMT 2023 (Pregunta 48)" },
  { question: "¿Qué consecuencia directa tiene una deficiente iluminación en el puesto de corte?", options: ["Fatiga ocular y mayor riesgo de cometer errores de posicionamiento o accidentes", "Mayor consumo eléctrico de la máquina", "Desgaste del motor de la escuadra"], correct: 0, explanation: "La falta de iluminación dificulta la lectura de marcas de corte y fatiga la visión del operario.", source: "Examen FNMT 2023 (Pregunta 49)" },
  { question: "¿En qué consiste el procedimiento de consignación LOTO antes de reparar la guillotina?", options: ["En el bloqueo mecánico y eléctrico de las fuentes de energía con candado e identificación", "En limpiar la mesa con aire", "En avisar verbalmente al compañero"], correct: 0, explanation: "LOTO garantiza que nadie pueda encender la máquina mientras el técnico está trabajando en ella.", source: "Examen FNMT 2023 (Pregunta 50)" },
  { question: "¿Cómo se deben clasificar los trapos impregnados de disolvente o restos de tintas?", options: ["Como residuos peligrosos que requieren almacenamiento cerrado y gestor autorizado", "Como basura urbana inerte", "Como papel reciclable"], correct: 0, explanation: "Son residuos tóxicos e inflamables que deben procesarse según la normativa ambiental estricta.", source: "Examen FNMT 2023 (Pregunta 51)" },
  { question: "¿Qué norma ISO especifica las condiciones para la Gestión Ambiental en las empresas?", options: ["ISO 14001", "ISO 9001", "ISO 27001"], correct: 0, explanation: "La norma ISO 14001 establece los requisitos para controlar el impacto ambiental en procesos industriales.", source: "Examen FNMT 2023 (Pregunta 52)" },
  { question: "¿Qué norma ISO define los requisitos de un Sistema de Gestión de la Calidad?", options: ["ISO 9001", "ISO 14001", "ISO 45001"], correct: 0, explanation: "La norma ISO 9001 es el estándar internacional aplicable para garantizar la calidad en los procesos.", source: "Examen FNMT 2023 (Pregunta 53)" },
  { question: "¿Qué norma ISO regula la estandarización del control de procesos en impresión Offset?", options: ["ISO 12647", "ISO 216", "ISO 9000"], correct: 0, explanation: "La norma ISO 12647 define las tolerancias de color, densidad y ganancia de punto para Offset.", source: "Examen FNMT 2023 (Pregunta 54)" },
  { question: "¿Cuáles son las medidas exactas de una hoja de tamaño ISO A4?", options: ["210 x 297 mm", "148 x 210 mm", "420 x 594 mm"], correct: 0, explanation: "El formato A4 internacional tiene dimensiones estandarizadas de 210 por 297 milímetros.", source: "Examen FNMT 2023 (Pregunta 55)" },
  { question: "¿Qué relación de aspecto geométrica mantienen todas las hojas de la serie ISO 216?", options: ["Proporción 1 : √2 (1 a raíz cuadrada de 2)", "Proporción 1 : 1,5", "Proporción 1 : 2 exactos"], correct: 0, explanation: "Esta proporción matemática permite dividir una hoja por la mitad conservando la misma forma.", source: "Examen FNMT 2023 (Pregunta 56)" },
  { question: "¿Qué área exacta abarca una pliego de formato ISO A0?", options: ["1 metro cuadrado (1 m²)", "0,5 metros cuadrados", "2 metros cuadrados"], correct: 0, explanation: "El pliego A0 se define como el origen de la serie con una superficie exacta de 1 m².", source: "Examen FNMT 2023 (Pregunta 57)" },
  { question: "¿Cuántos pliegos A4 se obtienen al cortar un pliego A0 sin desperdiciar papel?", options: ["16 pliegos A4", "8 pliegos A4", "32 pliegos A4"], correct: 0, explanation: "Un A0 equivale a 2 A1, 4 A2, 8 A3 y 16 pliegos A4.", source: "Examen FNMT 2023 (Pregunta 58)" },
  { question: "¿Qué gramaje presenta el papel fotocopia o común de oficina?", options: ["80 g/m²", "135 g/m²", "250 g/m²"], correct: 0, explanation: "El estándar común de reprografía o papel para fotocopiadoras es de 80 g/m².", source: "Examen FNMT 2023 (Pregunta 59)" },
  { question: "¿Qué máquina de acabado realiza surcos o deforma la fibra para facilitar el pliegue de cartulinas?", options: ["Hendidora", "Guillotina trilateral", "Grapadora continua"], correct: 0, explanation: "La hendidora marca una huella lineal en cartulinas para doblarlas sin romper el estuco exterior.", source: "Examen FNMT 2023 (Pregunta 60)" },
  { question: "¿Cuántos cortes se deben dar en la guillotina para dividir un pliego en 6 tiras independientes?", options: ["5 cortes", "6 cortes", "4 cortes"], correct: 0, explanation: "Para dividir un elemento continuo en N partes lineales se realizan N - 1 cortes (6 - 1 = 5).", source: "Examen FNMT 2023 (Pregunta 61)" },
  { question: "De un pliego de 700 x 1000 mm, ¿cuántas tarjetas de 100 x 70 mm se pueden cortar?", options: ["100 tarjetas", "70 tarjetas", "50 tarjetas"], correct: 0, explanation: "(700/70 = 10) por (1000/100 = 10), resultando 10 x 10 = 100 tarjetas exactas.", source: "Examen FNMT 2023 (Pregunta 62)" },
  { question: "De un pliego de 650 x 900 mm, ¿cuántas piezas de 200 x 300 mm se obtienen como máximo?", options: ["9 piezas", "6 piezas", "12 piezas"], correct: 0, explanation: "Dispuestas a (650/200 = 3) y (900/300 = 3), el máximo aprovechamiento es de 3 x 3 = 9 piezas.", source: "Examen FNMT 2023 (Pregunta 63)" },
  { question: "Si la merma estimada es del 5% y necesitamos 10.000 ejemplares netos, ¿cuántos pliegos se deben cortar?", options: ["10.526 pliegos en bruto", "10.050 pliegos", "9.500 pliegos"], correct: 0, explanation: "Se calcula dividiendo la cantidad neta entre el porcentaje utilizable: 10.000 / 0.95 = 10.526 pliegos.", source: "Examen FNMT 2023 (Pregunta 64)" },
  { question: "¿Qué máquina refila simultáneamente los tres lados abiertos (cabeza, pie y frente) de los libros?", options: ["Guillotina trilateral", "Guillotina monocuchilla", "Cizalladora rascadora"], correct: 0, explanation: "La trilateral cuenta con tres cuchillas que actúan en un solo ciclo para dejar el libro refilado.", source: "Examen FNMT 2023 (Pregunta 65)" },
  { question: "¿Qué tipo de encuadernación une las hojas sueltas aplicando adhesivo tras fresar el lomo?", options: ["Encuadernación rústica fresada (pegada)", "Cosida con hilo", "Grapada a caballete"], correct: 0, explanation: "El fresador crea canales en el lomo del bloque para que la cola penetre sujetando las hojas.", source: "Examen FNMT 2023 (Pregunta 66)" },
  { question: "¿Qué ventaja ofrece la cola termoplástica PUR sobre el Hot-Melt tradicional?", options: ["Gran flexibilidad, resistencia térmica y alta fuerza de pegado en papeles estucados", "Secado instantáneo en 0,1 segundos", "Coste económico más bajo"], correct: 0, explanation: "El adhesivo PUR reacciona con la humedad ambiental creando un pegado químicamente indestructible.", source: "Examen FNMT 2023 (Pregunta 67)" },
  { question: "¿Qué es una 'signatura' en el proceso de encuadernación?", options: ["El cuadernillo resultante al doblar un pliego impreso", "La firma del autor del libro", "El código de la bobina de papel"], correct: 0, explanation: "Las signaturas (cuadernillos de 8, 16 o 32 páginas) componen el cuerpo total de la obra.", source: "Examen FNMT 2023 (Pregunta 68)" },
  { question: "¿Qué proceso sigue al alzado de las signaturas en encuadernación cosida?", options: ["Cosido con hilo textil en cosedora automática y posterior encolado de lomo", "Plastificado de tripa", "Corte individual hoja por hoja"], correct: 0, explanation: "Tras colocar en orden las signaturas, la cosedora pasa el hilo por cada cuadernillo antes de poner la cubierta.", source: "Examen FNMT 2023 (Pregunta 69)" },
  { question: "¿En qué consiste la operación de 'alzado' de pliegos?", options: ["Ordenar de manera correlativa las signaturas impresas para formar la tripa del libro", "Subir la mesa de corte", "Aumentar la presión del pisón"], correct: 0, explanation: "El alzado es la secuencia que coloca un cuadernillo sobre otro en el orden correcto de lectura.", source: "Examen FNMT 2023 (Pregunta 70)" },
  { question: "¿Qué es el 'embuchado' de cuadernillos?", options: ["Insertar una signatura dentro de otra formando un conjunto anidado para grapa", "Meter pliegos en fundas de plástico", "Mezclar tintas"], correct: 0, explanation: "Se embuchan las signaturas unas dentro de otras para encuadernar revistas con grapas a lomo.", source: "Examen FNMT 2023 (Pregunta 71)" },
  { question: "¿Qué accesorio elimina la electricidad estática de las láminas plásticas en la guillotina?", options: ["Las barras ionizadoras o deselectrizadoras", "El pedal mecánico", "El aceite hidráulico"], correct: 0, explanation: "Las barras ionizadoras emiten cargas que neutralizan la estática facilitando la separación de láminas.", source: "Examen FNMT 2023 (Pregunta 72)" },
  { question: "Al cortar soportes plásticos sintéticos (PP o PVC), ¿qué problema genera la fricción rápida del filo?", options: ["Calentamiento y fusión de los bordes del plástico", "Falta de presión en el pisón", "Fallo de pantalla"], correct: 0, explanation: "La fricción rápida del acero genera calor que ablanda el plástico pegando los bordes del corte.", source: "Examen FNMT 2023 (Pregunta 73)" },
  { question: "¿Qué recubrimiento en la cuchilla evita que el plástico se adhiera al cortar sintéticos?", options: ["Recubrimiento de Teflón (PTFE)", "Baño de cobre", "Pintura sintética"], correct: 0, explanation: "El recubrimiento de teflón reduce la fricción y evita la adherencia térmica del plástico en el filo.", source: "Examen FNMT 2023 (Pregunta 74)" },
  { question: "¿Cómo se llama la mesa de acero cromado sobre la que reposa el papel en la máquina?", options: ["Mesa de corte o bancada", "Bastidor del pisón", "Chasis neumático"], correct: 0, explanation: "Es la superficie de trabajo pulida que alberga las válvulas de soplado e impacto de la cuchilla.", source: "Examen FNMT 2023 (Pregunta 75)" },
  { question: "¿Qué función cumple el visor o lente sobre la regla en guillotinas convencionales?", options: ["Aumentar la escala graduada para ajustar cotas con precisión milimétrica", "Iluminar el pisón", "Proyectar marcas de color"], correct: 0, explanation: "La lente de aumento facilita la lectura precisa de la posición de la escuadra eliminando errores.", source: "Examen FNMT 2023 (Pregunta 76)" },
  { question: "¿Qué es la 'suela del pisón'?", options: ["La superficie inferior plana del bloque de prensado que contacta con la pila de papel", "La base sobre el suelo", "El listón sintético"], correct: 0, explanation: "Es la pletina que ejerce la fuerza hidráulica de sujeción sobre la parte superior del papel.", source: "Examen FNMT 2023 (Pregunta 77)" },
  { question: "¿Por qué se exige aire comprimido seco y filtrado en los sistemas neumáticos?", options: ["Para evitar que el agua o aceite manchen los pliegos impresos y oxiden los canales", "Para no hacer ruido", "Para gastar menos energía"], correct: 0, explanation: "La presencia de agua o aceite en el aire de la mesa arruina el papel e inmoviliza las bolas neumáticas.", source: "Examen FNMT 2023 (Pregunta 78)" },
  { question: "¿Cuál es el beneficio principal del mantenimiento predictivo en guillotinas?", options: ["Detectar anomalías mecánicas antes de que provoquen averías o paradas no programadas", "Aumentar el peso de las hojas", "Eliminar operarios"], correct: 0, explanation: "Supervisar temperaturas, vibraciones y presiones previene paradas de producción inesperadas.", source: "Examen FNMT 2023 (Pregunta 79)" },
  { question: "En la FNMT, ¿qué protocolo se aplica a todo recorte sobrante de papel de seguridad impreso?", options: ["Custodia estricta, recuento y destrucción obligatoria en trituradoras supervisadas", "Reciclaje urbano común", "Regalo a terceros"], correct: 0, explanation: "Cualquier sobrante o maculatura de valor debe ser destruido bajo normas de máxima seguridad.", source: "Examen FNMT 2023 (Pregunta 80)" },
  { question: "¿Qué tipo de motor acciona el movimiento de la cuchilla en la guillotina POLAR 115?", options: ["Motor de corriente alterna con freno electromagnético", "Motor de corriente continua", "Motor neumático rotativo"], correct: 0, explanation: "Emplea motores de CA dotados de freno electromagnético para garantizar la detención instantánea.", source: "Examen FNMT 2023 (Pregunta 81)" },
  { question: "¿Cuál es la dureza del acero HSS del inserto de la cuchilla POLAR?", options: ["61 - 63 HRC", "18 - 20 HRC", "80 - 90 HRC"], correct: 0, explanation: "El inserto de aleación de acero rápido (HSS) alcanza entre 61 y 63 HRC de dureza.", source: "Examen FNMT 2023 (Pregunta 82)" },
  { question: "En la POLAR 115 XT, ¿cuál es la fuerza máxima del pedal mecánico?", options: ["300 N", "400 N", "500 N"], correct: 0, explanation: "La presión sobre el pedal de pre-presión está limitada por seguridad laboral a 300 N.", source: "Examen FNMT 2023 (Pregunta 83)" },
  { question: "¿Cuál es la presión de prensado recomendada para papel Offset?", options: ["2.000 daN", "3.000 daN", "1.000 daN"], correct: 0, explanation: "La presión estándar hidráulica configurada para papel offset normal es de 2.000 daN.", source: "Examen FNMT 2023 (Pregunta 84)" },
  { question: "¿Cómo se posiciona un papel con bajo deslizamiento en la mesa de corte?", options: ["Lo más a la izquierda posible", "Lo más a la derecha posible", "Es indiferente"], correct: 0, explanation: "Se coloca arrimado a la izquierda para reducir la fricción con la regla lateral fija derecha.", source: "Examen FNMT 2023 (Pregunta 85)" },
  { question: "¿Qué elemento absorbe el impacto final de la cuchilla al terminar la carrera?", options: ["El listón sintético o cuadradillo de corte", "La escuadra trasera", "El husillo de elevación"], correct: 0, explanation: "El listón sintético suave protege la arista del filo evitando su colisión con el metal.", source: "Examen FNMT 2023 (Pregunta 86)" },
  { question: "¿Cuántas posiciones útiles ofrece un listón de corte de sección cuadrada?", options: ["8 posiciones distintas", "4 posiciones distintas", "2 posiciones distintas"], correct: 0, explanation: "Un listón simétrico cuadrado ofrece 2 puntos de corte por cara (2 x 4 = 8 en total).", source: "Examen FNMT 2023 (Pregunta 87)" },
  { question: "¿Qué ángulo de bisel se recomienda para cortar papel estucado denso?", options: ["Ángulo doble de 24° a 26°", "Ángulo simple de 16°", "Ángulo de 45°"], correct: 0, explanation: "El doble bisel refuerza la arista del filo evitando muescas en papeles pesados.", source: "Examen FNMT 2023 (Pregunta 88)" },
  { question: "¿Qué sucede si el bisel es demasiado agudo (p. ej. 18°) en cartón duro?", options: ["El filo se dobla o mella rápidamente", "Aumenta la fuerza de soplado", "El pisón pierde presión"], correct: 0, explanation: "Carece del cuerpo de acero necesario para aguantar la penetración en soportes duros.", source: "Examen FNMT 2023 (Pregunta 89)" },
  { question: "¿Qué función cumple el soplado de la mesa (Eltrotact) en guillotinas POLAR?", options: ["Formar un colchón de aire que facilita el desplazamiento y mitiga la electricidad estática", "Enfriar la pantalla", "Aumentar la velocidad del pisón"], correct: 0, explanation: "El soplado reduce la fricción de las pilas pesadas y elimina la carga estática entre pliegos.", source: "Examen FNMT 2023 (Pregunta 90)" },
  { question: "¿Qué causa el defecto de corte conocido como 'corte en seta'?", options: ["Presión insuficiente del pisón o aire atrapado en la pila", "Cuchilla excesivamente afilada", "Avance rápido de la escuadra"], correct: 0, explanation: "Al no comprimirse adecuadamente la pila, las hojas de abajo se desplazan produciendo la deformación.", source: "Examen FNMT 2023 (Pregunta 91)" },
  { question: "¿Cómo se corrige el arqueamiento superior del bloque cortado?", options: ["Aumentando la presión del pisón y verificando el afilado de la cuchilla", "Disminuyendo la velocidad de la escuadra", "Limpiando la mesa con disolvente"], correct: 0, explanation: "Un filo desafilado empuja las hojas superiores si el pisón no ejerce la fuerza adecuada.", source: "Examen FNMT 2023 (Pregunta 92)" },
  { question: "¿Qué producto se aplica a las válvulas de bola de la mesa neumática?", options: ["Parafina seca especial", "Aceite mineral pesado de motor", "Grasa de litio concentrada"], correct: 0, explanation: "Las bolas deben lubricarse con parafina o ceras secas para evitar atascos por polvo de papel.", source: "Examen FNMT 2023 (Pregunta 93)" },
  { question: "¿Cuál es la tolerancia de precisión exigida en las guillotinas POLAR de alta gama?", options: ["±0,1 mm", "±1,0 mm", "±2,5 mm"], correct: 0, explanation: "Garantizan tolerancias estrictas de refilado de hasta una décima de milímetro.", source: "Examen FNMT 2023 (Pregunta 94)" },
  { question: "¿Qué comprobación de seguridad bimanual es obligatoria antes del turno?", options: ["Verificar que la máquina se detiene al soltar cualquiera de los dos mandos", "Revisar la presión de los neumáticos", "Ajustar la iluminación de la mesa"], correct: 0, explanation: "El circuito bimanual debe interrumpir inmediatamente la bajada de la cuchilla si se suelta una mano.", source: "Examen FNMT 2023 (Pregunta 95)" },
  { question: "¿Qué dispositivo evita el atrapamiento bloqueando la cuchilla si se interrumpe la zona de corte?", options: ["La barrera fotoeléctrica infrarroja", "El contador de cortes", "El potenciómetro de la escuadra"], correct: 0, explanation: "La cortina de luz detecta cualquier objeto y frena el embrague de la máquina al instante.", source: "Examen FNMT 2023 (Pregunta 96)" },
  { question: "¿Para qué sirve el pedal de pre-presión en la guillotina?", options: ["Bajar el pisón con baja presión para comprobar la línea visual de corte", "Realizar un corte rápido de emergencia", "Desplazar la escuadra trasera"], correct: 0, explanation: "Permite comprobar suavemente si la línea de corte coincide con el trazado sobre el pliego.", source: "Examen FNMT 2023 (Pregunta 97)" },
  { question: "¿Qué ventaja principal ofrece la cuchilla con encastre de carburo de tungsteno (Widia)?", options: ["Duración del afilado de 5 a 10 veces superior a la de acero HSS", "Mayor flexibilidad frente a impactos", "Menor peso estructural"], correct: 0, explanation: "Su extrema dureza permite realizar millones de cortes antes de requerir un nuevo afilado.", source: "Examen FNMT 2023 (Pregunta 98)" },
  { question: "¿Por qué no debe utilizarse una cuchilla de Widia para cortar papeles con grapas metálicas?", options: ["Porque el metal duro es frágil frente a impactos secos y se astilla", "Porque se oxida de inmediato", "Porque descalibra la pantalla táctil"], correct: 0, explanation: "A pesar de su gran resistencia al desgaste, la Widia se quiebra al golpear objetos metálicos duros.", source: "Examen FNMT 2023 (Pregunta 99)" },
  { question: "¿Qué ajuste se debe realizar tras instalar una cuchilla recién afilada?", options: ["Regulación de la profundidad de corte con la excéntrica de ajuste", "Sustitución de la bomba de aceite", "Aumento de la velocidad de la escuadra"], correct: 0, explanation: "Debido a la reducción de altura por el afilado, debe ajustarse el punto inferior para no penetrar en exceso el listón.", source: "Examen FNMT 2023 (Pregunta 100)" }
];



  


